			trackNumber: s.TrackNumber,
			mbid:        s.MbzTrackID,
			duration:    int(s.Duration),
			albumArtist: s.AlbumArtist,
			timestamp:   s.TimeStamp,
		})
		if err != nil {
			return err
		}
	}
	return nil
