package persistence

import (
	"context"

	"github.com/astaxie/beego/orm"
	"github.com/navidrome/navidrome/log"
	"github.com/navidrome/navidrome/model"
	"github.com/navidrome/navidrome/model/request"
	. "github.com/onsi/ginkgo"
	. "github.com/onsi/gomega"
)

var _ = Describe("UserPropsRepository", func() {
	var repo model.UserPropsRepository

	BeforeEach(func() {
		ctx := request.WithUser(log.NewContext(context.Background()), model.User{ID: "context-user"})
		repo = NewUserPropsRepository(ctx, orm.NewOrm())
	})

	It("uses the provided user ID for reads and writes, regardless of context", func() {
		const key = "user-props-isolation"
		Expect(repo.Put("user-a", key, "a-value")).To(Succeed())
		Expect(repo.Put("user-b", key, "b-value")).To(Succeed())

		value, err := repo.Get("user-a", key)
		Expect(err).ToNot(HaveOccurred())
		Expect(value).To(Equal("a-value"))
		value, err = repo.Get("user-b", key)
		Expect(err).ToNot(HaveOccurred())
		Expect(value).To(Equal("b-value"))
		_, err = repo.Get("context-user", key)
		Expect(err).To(MatchError(model.ErrNotFound))

		Expect(repo.Put("user-a", key, "updated-a-value")).To(Succeed())
		value, err = repo.DefaultGet("user-a", key, "default")
		Expect(err).ToNot(HaveOccurred())
		Expect(value).To(Equal("updated-a-value"))
		Expect(repo.Delete("user-a", key)).To(Succeed())
		value, err = repo.DefaultGet("user-a", key, "default")
		Expect(err).ToNot(HaveOccurred())
		Expect(value).To(Equal("default"))
		value, err = repo.Get("user-b", key)
		Expect(err).ToNot(HaveOccurred())
		Expect(value).To(Equal("b-value"))
		Expect(repo.Delete("user-b", key)).To(Succeed())
	})

	It("rejects an empty user ID for every operation", func() {
		Expect(repo.Put("", "key", "value")).To(MatchError(model.ErrInvalidAuth))
		_, err := repo.Get("", "key")
		Expect(err).To(MatchError(model.ErrInvalidAuth))
		_, err = repo.DefaultGet("", "key", "default")
		Expect(err).To(MatchError(model.ErrInvalidAuth))
		Expect(repo.Delete("", "key")).To(MatchError(model.ErrInvalidAuth))
	})
})
package tests

import (
	"testing"

	"github.com/navidrome/navidrome/model"
)

func TestMockedUserPropsRepoScopesCompositeKeys(t *testing.T) {
	repo := &MockedUserPropsRepo{}
	// These pairs collide when joined with an underscore.
	if err := repo.Put("a_b", "c", "first"); err != nil {
		t.Fatal(err)
	}
	if err := repo.Put("a", "b_c", "second"); err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct{ userID, key, want string }{
		{"a_b", "c", "first"},
		{"a", "b_c", "second"},
	} {
		got, err := repo.DefaultGet(tc.userID, tc.key, "default")
		if err != nil || got != tc.want {
			t.Errorf("DefaultGet(%q, %q) = %q, %v; want %q", tc.userID, tc.key, got, err, tc.want)
		}
	}
	if err := repo.Delete("a_b", "c"); err != nil {
		t.Fatal(err)
	}
	if got, err := repo.Get("a", "b_c"); err != nil || got != "second" {
		t.Errorf("deleting another user's property changed this value: got %q, %v", got, err)
	}
	if got, err := repo.DefaultGet("a_b", "c", "default"); err != nil || got != "default" {
		t.Errorf("missing property default = %q, %v; want default", got, err)
	}
}

func TestMockedUserPropsRepoRequiresUserID(t *testing.T) {
	repo := &MockedUserPropsRepo{}
	if err := repo.Put("", "key", "value"); err != model.ErrInvalidAuth {
		t.Errorf("Put without user ID = %v; want ErrInvalidAuth", err)
	}
	if _, err := repo.Get("", "key"); err != model.ErrInvalidAuth {
		t.Errorf("Get without user ID = %v; want ErrInvalidAuth", err)
	}
	if _, err := repo.DefaultGet("", "key", "default"); err != model.ErrInvalidAuth {
		t.Errorf("DefaultGet without user ID = %v; want ErrInvalidAuth", err)
	}
	if err := repo.Delete("", "key"); err != model.ErrInvalidAuth {
		t.Errorf("Delete without user ID = %v; want ErrInvalidAuth", err)
	}
}
package lastfm

import (
	"bytes"
	"context"
	"crypto/hmac"
	"crypto/sha256"
	_ "embed"
	"encoding/base64"
	"encoding/json"
	"errors"
	"net/http"
	"strings"
	"time"

	"github.com/deluan/rest"
	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
	"github.com/navidrome/navidrome/conf"
	"github.com/navidrome/navidrome/consts"
	"github.com/navidrome/navidrome/core/auth"
	"github.com/navidrome/navidrome/log"
	"github.com/navidrome/navidrome/model"
	"github.com/navidrome/navidrome/model/request"
	"github.com/navidrome/navidrome/server"
	"github.com/navidrome/navidrome/utils"
)

const (
	linkStateLifetime = 5 * time.Minute
	linkStatePurpose  = "lastfm-link-v1"
)

type linkStatePayload struct {
	UserID    string `json:"uid"`
	ExpiresAt int64  `json:"exp"`
}

//go:embed token_received.html
var tokenReceivedPage []byte

type Router struct {
	http.Handler
	ds          model.DataStore
	sessionKeys *sessionKeys
	client      *Client
	apiKey      string
	secret      string
}

func NewRouter(ds model.DataStore) *Router {
	r := &Router{
		ds:          ds,
		apiKey:      conf.Server.LastFM.ApiKey,
		secret:      conf.Server.LastFM.Secret,
		sessionKeys: &sessionKeys{ds: ds},
	}
	r.Handler = r.routes()
	hc := &http.Client{
		Timeout: consts.DefaultHttpClientTimeOut,
	}
	r.client = NewClient(r.apiKey, r.secret, "en", hc)
	return r
}

func (s *Router) routes() http.Handler {
	r := chi.NewRouter()

	r.Group(func(r chi.Router) {
		r.Use(server.Authenticator(s.ds))
		r.Use(server.JWTRefresher)

		r.Get("/link", s.getLinkStatus)
		r.Get("/link/start", s.startLink)
		r.Delete("/link", s.unlink)
	})

	r.Get("/link/callback", s.callback)

	return r
}

func (s *Router) getLinkStatus(w http.ResponseWriter, r *http.Request) {
	userID := authenticatedUserID(r)
	if userID == "" {
		_ = rest.RespondWithError(w, http.StatusUnauthorized, "Not authenticated")
		return
	}
	resp := map[string]interface{}{"status": true}
	key, err := s.sessionKeys.get(r.Context(), userID)
	if err != nil && err != model.ErrNotFound {
		resp["error"] = err
		resp["status"] = false
		_ = rest.RespondWithJSON(w, http.StatusInternalServerError, resp)
		return
	}
	resp["status"] = key != ""
	_ = rest.RespondWithJSON(w, http.StatusOK, resp)
}

func (s *Router) startLink(w http.ResponseWriter, r *http.Request) {
	userID := authenticatedUserID(r)
	if userID == "" {
		_ = rest.RespondWithError(w, http.StatusUnauthorized, "Not authenticated")
		return
	}
	state, err := signLinkState(userID)
	if err != nil {
		_ = rest.RespondWithError(w, http.StatusInternalServerError, "Could not start Last.fm authorization")
		return
	}
	_ = rest.RespondWithJSON(w, http.StatusOK, map[string]string{"state": state})
}

func (s *Router) unlink(w http.ResponseWriter, r *http.Request) {
	userID := authenticatedUserID(r)
	if userID == "" {
		_ = rest.RespondWithError(w, http.StatusUnauthorized, "Not authenticated")
		return
	}
	err := s.sessionKeys.delete(r.Context(), userID)
	if err != nil {
		_ = rest.RespondWithError(w, http.StatusInternalServerError, err.Error())
	} else {
		_ = rest.RespondWithJSON(w, http.StatusOK, map[string]string{})
	}
}

func (s *Router) callback(w http.ResponseWriter, r *http.Request) {
	token := utils.ParamString(r, "token")
	if token == "" {
		_ = rest.RespondWithError(w, http.StatusBadRequest, "token not received")
		return
	}
	uid, err := verifyLinkState(utils.ParamString(r, "state"))
	if err != nil {
		_ = rest.RespondWithError(w, http.StatusBadRequest, "invalid authorization state")
		return
	}

	ctx := r.Context()
	err = s.fetchSessionKey(ctx, uid, token)
	if err != nil {
		w.Header().Set("Content-Type", "text/plain; charset=utf-8")
		w.WriteHeader(http.StatusBadRequest)
		_, _ = w.Write([]byte("An error occurred while authorizing with Last.fm. \n\nRequest ID: " + middleware.GetReqID(ctx)))
		return
	}

	http.ServeContent(w, r, "response", time.Now(), bytes.NewReader(tokenReceivedPage))
}

func (s *Router) fetchSessionKey(ctx context.Context, uid, token string) error {
	sessionKey, err := s.client.GetSession(ctx, token)
	if err != nil {
		log.Error(ctx, "Could not fetch LastFM session key", "userId", uid, "token", token,
			"requestId", middleware.GetReqID(ctx), err)
		return err
	}
	err = s.sessionKeys.put(ctx, uid, sessionKey)
	if err != nil {
		log.Error("Could not save LastFM session key", "userId", uid, "requestId", middleware.GetReqID(ctx), err)
	}
	return err
}

func authenticatedUserID(r *http.Request) string {
	user, ok := request.UserFrom(r.Context())
	if !ok {
		return ""
	}
	return user.ID
}

func signLinkState(userID string) (string, error) {
	if userID == "" || len(auth.Secret) == 0 {
		return "", errors.New("missing user or signing secret")
	}
	payload, err := json.Marshal(linkStatePayload{UserID: userID, ExpiresAt: time.Now().Add(linkStateLifetime).Unix()})
	if err != nil {
		return "", err
	}
	encoded := base64.RawURLEncoding.EncodeToString(payload)
	return encoded + "." + base64.RawURLEncoding.EncodeToString(linkStateSignature(encoded)), nil
}

func verifyLinkState(state string) (string, error) {
	parts := strings.Split(state, ".")
	if len(parts) != 2 || len(auth.Secret) == 0 {
		return "", errors.New("invalid authorization state")
	}
	signature, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil || !hmac.Equal(signature, linkStateSignature(parts[0])) {
		return "", errors.New("invalid authorization state")
	}
	payload, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		return "", err
	}
	var data linkStatePayload
	if err = json.Unmarshal(payload, &data); err != nil {
		return "", err
	}
	if data.UserID == "" || data.ExpiresAt <= time.Now().Unix() {
		return "", errors.New("expired or incomplete authorization state")
	}
	return data.UserID, nil
}

func linkStateSignature(payload string) []byte {
	mac := hmac.New(sha256.New, auth.Secret)
	_, _ = mac.Write([]byte(linkStatePurpose + "." + payload))
	return mac.Sum(nil)
}

