func TestRouterLinkOperationsUseAuthenticatedUser(t *testing.T) {
	secret := auth.Secret
	auth.Secret = []byte("lastfm-router-test-secret")
	t.Cleanup(func() { auth.Secret = secret })

	ds := &tests.MockDataStore{}
	props := ds.UserProps(nil)
	if err := props.Put("user-a", sessionKeyProperty, "a-session"); err != nil {
		t.Fatal(err)
	}
	router := &Router{sessionKeys: &sessionKeys{ds: ds}}

	requestFor := func(userID, path string) *http.Request {
		r := httptest.NewRequest(http.MethodGet, path, nil)
		return r.WithContext(request.WithUser(r.Context(), model.User{ID: userID}))
	}

	status := httptest.NewRecorder()
	router.getLinkStatus(status, requestFor("user-b", "/link"))
	if status.Code != http.StatusOK || !bytes.Contains(status.Body.Bytes(), []byte(`"status":false`)) {
		t.Fatalf("user B link status = %d %s; want unlinked", status.Code, status.Body.String())
	}

	start := httptest.NewRecorder()
	router.startLink(start, requestFor("user-b", "/link/start"))
	if start.Code != http.StatusOK {
		t.Fatalf("start link = %d %s", start.Code, start.Body.String())
	}
	var response struct {
		State string `json:"state"`
	}
	if err := json.Unmarshal(start.Body.Bytes(), &response); err != nil {
		t.Fatal(err)
	}
	if userID, err := verifyLinkState(response.State); err != nil || userID != "user-b" {
		t.Fatalf("signed state user = %q, %v; want user-b", userID, err)
	}

	if err := props.Put("user-b", sessionKeyProperty, "b-session"); err != nil {
		t.Fatal(err)
	}
	unlink := httptest.NewRecorder()
	router.unlink(unlink, requestFor("user-b", "/link"))
	if unlink.Code != http.StatusOK {
		t.Fatalf("unlink = %d %s", unlink.Code, unlink.Body.String())
	}
	if got, err := props.Get("user-a", sessionKeyProperty); err != nil || got != "a-session" {
		t.Fatalf("unlinking B changed A's session: %q, %v", got, err)
	}
	if _, err := props.Get("user-b", sessionKeyProperty); err != model.ErrNotFound {
		t.Fatalf("B's session remains after unlink: %v", err)
	}

	for _, handler := range []http.HandlerFunc{router.getLinkStatus, router.startLink, router.unlink} {
		unauthenticated := httptest.NewRecorder()
		handler(unauthenticated, httptest.NewRequest(http.MethodGet, "/link", nil))
		if unauthenticated.Code != http.StatusUnauthorized {
			t.Errorf("handler without user returned %d; want 401", unauthenticated.Code)
		}
	}
}

func TestRouterCallbackRequiresSignedUserState(t *testing.T) {
	secret := auth.Secret
	auth.Secret = []byte("lastfm-router-test-secret")
	t.Cleanup(func() { auth.Secret = secret })

	ds := &tests.MockDataStore{}
	props := ds.UserProps(nil)
	if err := props.Put("user-b", sessionKeyProperty, "b-session"); err != nil {
		t.Fatal(err)
	}
	httpClient := &tests.FakeHttpClient{Res: http.Response{
		Body:       io.NopCloser(strings.NewReader(`{"session":{"key":"a-session"}}`)),
		StatusCode: http.StatusOK,
	}}
	router := &Router{sessionKeys: &sessionKeys{ds: ds}, client: NewClient("api-key", "secret", "en", httpClient)}
	state, err := signLinkState("user-a")
	if err != nil {
		t.Fatal(err)
	}
	parts := strings.Split(state, ".")
	forgedPayload, err := json.Marshal(linkStatePayload{UserID: "user-b", ExpiresAt: time.Now().Add(linkStateLifetime).Unix()})
	if err != nil {
		t.Fatal(err)
	}
	forgedState := base64.RawURLEncoding.EncodeToString(forgedPayload) + "." + parts[1]

	for _, candidate := range []string{"", forgedState} {
		callback := httptest.NewRecorder()
		router.callback(callback, httptest.NewRequest(http.MethodGet, "/link/callback?token=lastfm-token&uid=user-b&state="+url.QueryEscape(candidate), nil))
		if callback.Code != http.StatusBadRequest {
			t.Errorf("callback with invalid state returned %d; want 400", callback.Code)
		}
	}
	if httpClient.RequestCount != 0 {
		t.Fatalf("invalid state triggered %d Last.fm requests", httpClient.RequestCount)
	}

	callback := httptest.NewRecorder()
	router.callback(callback, httptest.NewRequest(http.MethodGet, "/link/callback?token=lastfm-token&uid=user-b&state="+url.QueryEscape(state), nil))
	if callback.Code != http.StatusOK {
		t.Fatalf("valid callback = %d %s", callback.Code, callback.Body.String())
	}
	if got, err := props.Get("user-a", sessionKeyProperty); err != nil || got != "a-session" {
		t.Fatalf("A's session = %q, %v; want a-session", got, err)
	}
	if got, err := props.Get("user-b", sessionKeyProperty); err != nil || got != "b-session" {
		t.Fatalf("callback changed B's session: %q, %v", got, err)
	}

	expiredPayload, err := json.Marshal(linkStatePayload{UserID: "user-a", ExpiresAt: time.Now().Add(-time.Minute).Unix()})
	if err != nil {
		t.Fatal(err)
	}
	encoded := base64.RawURLEncoding.EncodeToString(expiredPayload)
	expiredState := encoded + "." + base64.RawURLEncoding.EncodeToString(linkStateSignature(encoded))
	if _, err := verifyLinkState(expiredState); err == nil {
		t.Fatal("expired state was accepted")
	}
}
